INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64710898', 64710898, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Konsultan Perancangan Strategi Komunikasi dan Pelaporan Kinerja SDI', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 137940000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Memberikan dukungan perumusan strategi komunikasi publik dalam rangka sosialisasi dan kampanye inisiatif Satu Data Indonesia; Melakukan pengelolaan komunikasi antara Produsen Data dan Walidata di Instansi Pemerintah Pusat, serta Koordinator Forum SDI Daerah dan Walidata di Pemerintah Daerah melalui platform digital (Grup Whatsapp, Telegram, Forum Digital di Portal SDI); Melakukan koordinasi, asistensi/pendampingan, dan menjadi narahubung serta juru bicara untuk Kementerian/Lembaga/Daerah (K/L/D) guna penyebarluasan informasi dan pelaksanaan kegiatan terkait', 'Dokumen Strategi Komunikasi Publik yang meliputi: Rencana sosialisasi Satu Data Indonesia dalam meningkatkan kesadaran dan pemahaman masyarakat serta pemangku kepentingan; dan Kampanye inisiatif Satu Data Indonesia dalam meningkatkan kesadaran dan pemahaman masyarakat serta pemangku kepentingan. Laporan Kinerja Periodik Satu Data Indonesia (Semester I, Semester II, Akhir Tahun) untuk melaporkan capaian kegiatan Satu Data Indonesia kepada pihak internal Bappenas, Kelompok Kerja SDI, Forum SDI, Pemerintah Daerah dan stakeholder lain. Struktur dan Metodologi Laporan Penyelenggaraan Satu Data Indonesia Tingkat Pusat dan Tingkat Daerah dalam penyusunan Laporan Penyelenggaraan Satu Data Indonesia Tingkat Pusat dan Tingkat Daerah. Laporan Koordinasi dengan Kementerian/Lembaga/Daerah (K/L/D) yang meliputi: Laporan kegiatan koordinasi dengan Kementerian/Lembaga/Daerah (K/L/D) Laporan asistensi/pendampingan dengan Kementerian/Lembaga/Daerah (K/L/D); dan Laporan rangkuman Frequently Asked Question (FAQ) selama menjadi narahubung serta juru bicara untuk Kementerian/Lembaga/Daerah dalam rangka penyebarluasan informasi dan pelaksanaan kegiatan terkait inisiatif Satu Data Indonesia. Laporan Dokumentasi Komunikasi Digital SDI dalam mencatat aktivitas dan komunikasi digital SDI termasuk bentuk foto dan video yang mendukung pelaporan dan penyimpanan arsip kegiatan SDI; dan Laporan penugasan lainnya yang diberikan oleh Koordinator Sekretariat SDI Pusat, Koordinator Bidang Administrasi Sekretariat SDI Pusat dan/atau Manager Bidang Komunikasi Sekretariat SDI Pusat; Laporan bulanan Tenaga Tenaga Ahli Strategi Komunikasi dan Pelaporan Kinerja Satu Data Indonesia Tahun Anggaran 2026 memuat rekam pelaksanaan pekerjaan setiap bulannya dalam rangka mencapai keluaran sebagaimana pada nomor 1 sampai dengan nomor 5; Laporan Akhir pelaksanaan kontrak Tenaga Ahli Strategi Komunikasi dan Pelaporan Kinerja Satu Data Indonesia Tahun Anggaran 2026 memuat keluaran sebagaimana pada nomor 1 sampai dengan nomor 5;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1689024);
